-- WhatsNew.lua: generated from CHANGELOG.md by the release (make_whatsnew.py; do not edit by hand).
-- Per version: v, date, items = { { s = "add"|"chg"|"fix", fr = { title, text }, en = { title, text } } }
local _, ns = ...
ns.WHATSNEW = {
  { v = "1.0.0-beta.204", date = "2026-11-22", items = {
    { s = "chg", fr = { "La chaîne du set de donjon 2 sort des trajets de donjon", "An Earnest Proposition ouvre une suite de classe d'une vingtaine de quêtes (Silithus, Stratholme, Blackrock Depths, puis l'amulette de Valthalak dans l'un des quatre donjons). Ce n'est pas une quête de donjon. Même commencée, elle ne remplit plus le trajet de LBRS ou d'un autre donjon : l'aperçu la montre verrouillée comme chaîne longue. Coche-la pour la suivre. Quand seule l'étape du donjon reste à faire, elle revient d'elle-même." }, en = { "The Dungeon Set 2 class chain stays out of dungeon routes, even started, unless ticked by hand or down to the dungeon's own step.", "" } },
  } },
  { v = "1.0.0-beta.203", date = "2026-11-22", items = {
    { s = "add", fr = { "Rapport automatique des quêtes renumérotées", "Quand le guide reconnaît par son titre une quête du journal dont le numéro nous est inconnu, il envoie tout seul un rapport discret à l'équipe WL Helper, une fois par numéro, pour qu'on l'ajoute aux données. An Earnest Proposition 84157 (vue chez un mage Horde) est déjà ajoutée." }, en = { "A renumbered quest recognised by its title is reported once, quietly, so its number goes into the data; An Earnest Proposition 84157 added.", "" } },
  } },
  { v = "1.0.0-beta.202", date = "2026-11-22", items = {
    { s = "fix", fr = { "Les quêtes que Forever a renumérotées", "Quelques quêtes connues ont un nouveau numéro sur Forever, par exemple An Earnest Proposition chez Mokvar (97411) ou les Just Compensation du set de donjon 2. Le guide ne les voyait pas dans ton journal et disait toujours « Accepter ». Maintenant, une quête du journal au numéro inconnu mais au titre connu compte pour la nôtre, si ton personnage peut la faire (faction, classe, race) : prise, prête à rendre, puis faite une fois rendue. Le nouveau numéro est retenu pour la suite de la chaîne." }, en = { "Quests Forever renumbered (An Earnest Proposition 97411, Just Compensation…) are recognised by their title, so the guide sees them taken, ready and turned in.", "" } },
  } },
  { v = "1.0.0-beta.201", date = "2026-11-22", items = {
    { s = "add", fr = { "Voleurs : le Talisman of Kazdor", ", avec toute la suite de Fahrad : Fool Me Twice, The Talisman of Kazdor, Best Laid Plans, One Last Drop et Biding Our Time. La dernière rapporte le Filcher's Cowl et la Rune of the Coterie. La quête du donjon explique la marche à suivre : les deux Vile Concoction dans le chaudron d'Antu'sul, la tombe qui brille, le Hollow Emblem sur la corniche, puis Nekrum assommé. La suite n'est proposée qu'après The Eye of Bhossca, la chaîne de voleur d'avant. Tout a été lu sur Wowhead WoW Forever." }, en = { "Rogues", "The Talisman of Kazdor (Zul'Farrak, solo) and Fahrad's whole chain, offered once The Eye of Bhossca is done, with the walkthrough; read on Wowhead WoW Forever." } },
  } },
  { v = "1.0.0-beta.200", date = "2026-11-22", items = {
    { s = "add", fr = { "Le début des suites de classe et Ramstein", "The Azure Key (voleur), Voodoo Feathers (guerrier) et A Better Ingredient (druide) disent maintenant où leur suite commence. C'est chez ton maître de classe : A Simple Request, A Troubled Spirit, Torwa Pathfinder. Ramstein dit qu'il faut d'abord « Duskwing, Oh How I Hate Thee... ». Tout a été vérifié sur Wowhead WoW Forever, qui corrige ForeverDungeonJournal sur deux points : les quêtes de classe ne sont pas facultatives, et Ramstein ne suit pas The Champion of the Banshee Queen." }, en = { "The rogue, warrior and druid chains say where they start (the class trainer), and Ramstein says it needs Duskwing first; checked on Wowhead WoW Forever.", "" } },
  } },
  { v = "1.0.0-beta.199", date = "2026-11-22", items = {
    { s = "add", fr = { "Les quêtes d'introduction", "Comparé à Naowh Dungeon Journal et ForeverDungeonJournal, il nous manquait des quêtes Horde qui mènent à une quête de donjon. Chacune a été vérifiée sur Wowhead WoW Forever (qui la donne, où elle mène, à quel niveau). Elles sont ajoutées comme une note sur la quête qu'elles annoncent, pas comme une étape (elles sont facultatives et allongeraient le trajet) : Tran'rek (Scarab Shells), Tabetha's Task pour les mages (Tiara of the Deep), Vivian Lagrave (Lost Thunderbrew Recipe), Yuka Screwspigot (Ribbly Screwspigot), Vivian Lagrave and the Darkstone Tablet (The Darkstone Tablet), Camp Mojache (Lethtendris's Web), et le début de la suite de voleur A Simple Request (The Azure Key)." }, en = { "Horde breadcrumb quests found in Naowh's and ForeverDungeonJournal's lists, each checked on Wowhead WoW Forever, now appear as a note on the quest they lead to.", "" } },
  } },
  { v = "1.0.0-beta.198", date = "2026-11-22", items = {
    { s = "chg", fr = { "Les réputations ont leur propre page", "Dans la fenêtre WL Helper, sous Progresser, au même niveau que les autres pages : le nombre de réputations, les pièces de ta liste qu'elles débloquent, puis une carte par faction avec ses quêtes. La ligne « Réputations » de l'accueil et /wlh rep ouvrent cette page. L'onglet Réputations quitte la fenêtre « Meilleur équipement », où il n'avait pas sa place." }, en = { "Reputations have their own page in the WL Helper window, under Progress; Home's \"Reputations\" line and /wlh rep open it, and the tab left the Best gear window.", "" } },
    { s = "fix", fr = { "Blackmaw Pouches répétable", "Avec « toutes les quêtes » activé (/wlh tout), le guide proposait la version répétable (96246) alors que la première (97327) était encore dans le journal. Une répétable attend maintenant que sa première version soit rendue." }, en = { "The repeatable Blackmaw Pouches waits until the first one is turned in, even with every quest on.", "" } },
  } },
  { v = "1.0.0-beta.197", date = "2026-11-22", items = {
    { s = "chg", fr = { "L'accueil a une section « Cette semaine »", "Deux cartes côte à côte, l'hebdo PvE et l'hebdo PvP, avec le temps restant avant la remise à zéro. L'hebdo PvE, c'est le sac de l'Undermine : où tu en es (à faire, en cours, faite), ce qu'il faut ramener des trois ailes de Hache-Tripes, où aller (Pix Xizzix, Baie-du-Butin), ce que ça rapporte (10 à 100 po), « Y aller » avec le GPS et « Voir le guide ». L'hebdo PvP donne le champ de bataille en bonus d'après le calendrier du jeu et son maître de guerre, la quête Field of Honor, ce que ça rapporte, ta place au classement de la guilde, « Y aller » et « Champs de bataille »." }, en = { "Home has a \"This week\" section", "The PvE weekly (Undermine Satchel: where you stand, what, where, reward, GPS and its guide) and the PvP weekly (bonus battleground, Field of Honor, reward, guild ranking), with the time left before the weekly reset." } },
    { s = "chg", fr = { "Un accueil mieux équilibré", "Les activités tiennent en deux lignes de deux cartes (Progresser, Argent et métiers, Guilde et groupes, Voyager), même sur une fenêtre large. La carte PvP, presque vide, laisse sa place à l'hebdo PvP. « Nous écrire » devient un bandeau fin en bas de la page." }, en = { "A more balanced Home", "The activities fit in two rows of two cards, the near-empty PvP card gives way to the PvP weekly, and \"Write to us\" becomes a thin strip at the bottom." } },
    { s = "chg", fr = { "L'hebdo n'est plus dans l'onglet Quêtes", "Du choix des guides : il est sur l'accueil. La recherche du choix des guides le trouve encore." }, en = { "The weekly left the guide picker's Quests tab (it is on Home now); the picker's search still finds it.", "" } },
    { s = "chg", fr = { "Le guide des réputations se trouve enfin", "Une ligne « Réputations » dans la carte Progresser de l'accueil, et une entrée dans le menu de gauche sous Progresser. Les deux ouvrent directement l'onglet Réputations." }, en = { "The reputations guide is easy to find", "A \"Reputations\" line in Home's Progress card and an entry under Progress in the left menu, both opening the Reputations tab." } },
    { s = "add", fr = { "Réputations : la liste des quêtes", "La carte de chaque faction liste ses quêtes, cochées si elles sont faites, \"en cours\" si elles sont dans ton journal, avec le rang requis sinon. Pour l'instant Grumegueule (37 quêtes, d'après le guide de réputation de Wowhead WoW Forever)." }, en = { "Each reputation card lists the faction's quests, ticked when done (Timbermaw Hold for now).", "" } },
  } },
  { v = "1.0.0-beta.196", date = "2026-11-22", items = {
    { s = "fix", fr = { "Plus de quête que tu ne peux pas prendre à cause de ta réputation", "Une quête qui demande une réputation que tu n'as pas sort du trajet. Elle apparaît comme verrouillée, avec la raison (« réputation Timbermaw Hold requise : Neutre »), et revient dès que tu l'as. Ça concerne d'abord les quêtes de Blackmaw Hold en Azshara (Neutre avec Grumegueule), sauf The Legashi Threat qui se prend sans réputation. Une quête déjà dans ton journal reste dans le trajet." }, en = { "A quest that needs a reputation you do not have leaves the route, locked with the reason, and comes back once you have it (Blackmaw Hold's Azshara quests: Neutral with Timbermaw Hold).", "" } },
  } },
  { v = "1.0.0-beta.195", date = "2026-11-22", items = {
    { s = "add", fr = { "Blackmaw Hold : le début de la chaîne et la réputation", "The Legashi Threat (Ekkal, en Azshara) commence tout et ne demande aucune réputation. Report to Rageroar et Missing Blackmaw Scouts (Horde) mènent ensuite à Korsa. Les quêtes de Gatekeeper Rageroar et de Gorn One Eye disent maintenant qu'il faut être Neutre avec Grumegueule. La note d'Ekkal explique le plus rapide pour y arriver : Legashi Horns, 5 cornes pour 100 de réputation. Lu sur Wowhead WoW Forever (pages des quêtes et guide de réputation Grumegueule)." }, en = { "Blackmaw Hold", "The Legashi Threat starts the chain with no reputation needed; Report to Rageroar and Missing Blackmaw Scouts lead to Korsa; Rageroar's and Gorn's quests say Neutral with Timbermaw Hold is needed, and how to get there fast (Legashi Horns)." } },
  } },
  { v = "1.0.0-beta.194", date = "2026-11-22", items = {
    { s = "add", fr = { "/wlh gearscan", "Relève dans ton jeu les objets des listes BiS de Naowh que WL Helper Gear ne connaît pas (sets de Forever, Mark of Fordring, certains bijoux et armes). Il garde leurs statistiques, leur emplacement, leur niveau et les lignes de leur infobulle (effets « Utiliser » et « Chance quand vous touchez »). Fais /reload ensuite pour enregistrer. Ça sert à compléter WL Helper Gear avec les vraies valeurs du jeu. Rien n'est envoyé." }, en = { "/wlh gearscan reads in your game the BiS items WL Helper Gear does not list (stats, slot, level, tooltip lines), saved after a /reload, to complete Gear with the game's own values.", "" } },
  } },
  { v = "1.0.0-beta.193", date = "2026-11-22", items = {
    { s = "chg", fr = { "Les flèches suivent la liste BiS", "Quand l'objet de ton sac et celui que tu portes sont tous les deux dans la liste BiS de Naowh pour ta spé, c'est l'ordre de la liste qui décide de la flèche verte, plus le calcul de WL Helper. L'infobulle le dit : « Liste BiS de Naowh : n°2, mieux que ton objet (n°5). À prendre. » ou « ... moins bien que ton objet. Garde le tien. ». Si l'un des deux n'est pas dans la liste, rien ne change. Les armes gardent le calcul." }, en = { "When both the bag item and the worn one are in Naowh's BiS list for your spec, the list's order decides the arrow; the tooltip gives both ranks.", "" } },
    { s = "chg", fr = { "WL Helper Gear deux fois plus léger", "Chaque objet ne garde plus que ses statistiques non nulles. La mémoire passe d'environ 20 Mo à 10 Mo, avec exactement les mêmes notes (vérifiées sur les 28 spés)." }, en = { "WL Helper Gear keeps only each item's non-zero stats", "About 20 MB down to 10 MB, same scores." } },
  } },
  { v = "1.0.0-beta.192", date = "2026-11-22", items = {
    { s = "add", fr = { "Le parcours dans les rapports", "WL Helper note les quêtes prises et rendues (avec l'étape du guide à ce moment-là) et les boss tués en donjon, avec le temps depuis l'entrée. En sortant d'un donjon (après au moins 5 minutes dedans), il envoie en silence un rapport « parcours » : le donjon, sa durée, l'ordre des boss et les quêtes. Ça sert à vérifier l'ordre des guides avec de vraies parties. Par la guilde, à l'auteur seulement. Pour le couper : /wlh rapports parcours off." }, en = { "Quests taken and turned in (with the guide step) and boss kills with their time go in a silent \"run\" report when you leave a dungeon (/wlh rapports parcours off stops it).", "" } },
    { s = "fix", fr = { "Clic sur l'étape en cours", "Cliquer sur la carte de l'étape pouvait donner une erreur quand la ligne du lieu était cachée." }, en = { "Clicking the current step no longer errors when its place line is hidden.", "" } },
    { s = "fix", fr = { "Flèches sur les sacs", "Avec beaucoup d'addons, le parcours de toutes les fenêtres du jeu dépassait le temps permis. Il se fait maintenant par petits morceaux." }, en = { "The bag arrows no longer hit \"script ran too long\" with many addons.", "" } },
  } },
  { v = "1.0.0-beta.191", date = "2026-11-22", items = {
    { s = "fix", fr = { "Sacs, « Libérer une place » ne jette plus ce qu'une quête demande", "Une quête de la Croisée demande des armes et des boucliers blancs, et le nettoyeur les jetait comme des objets inutiles. Un objet qu'un objectif de ton journal de quêtes demande (« Worn Shield : 1/5 ») reste maintenant dans tes sacs, qu'il soit blanc ou gris. La vente automatique des objets gris chez un marchand suit la même règle." }, en = { "Bags", "\"Free a slot\" and the grey item selling keep every item a quest of your log asks for." } },
  } },
  { v = "1.0.0-beta.190", date = "2026-11-22", items = {
    { s = "fix", fr = { "Les rapports arrivent enfin chez l'auteur de WL Helper", "Les rapports (« Nous écrire », erreurs automatiques, quêtes introuvables, mesures de mémoire) partaient vers le chef de guilde, qui ne les recevait pas, et n'arrivaient donc nulle part. Ils vont maintenant au personnage de l'auteur de l'addon, dès qu'il est connecté en même temps que le joueur. En attendant, ils restent en attente chez le joueur. Les rapports déjà en attente partiront tout seuls." }, en = { "Reports now go to WL Helper's author (they were addressed to the guild master and never arrived).", "" } },
  } },
}
